(1, 'Karibu kwenye uzoefu mpya wa parokia', 'karibu-kwenye-uzoefu-mpya-wa-parokia', 'Mwonekano huu mpya wa mwanzo umeundwa kufanya taarifa za parokia ziwe rahisi kupatikana na zenye kuvutia kutazamwa.', '<p>Ukurasa huu unaweza kuhaririwa na wasimamizi mara tu sehemu za CMS zitakapoongezwa.</p>', NULL, '2026-04-02 21:07:11', NULL, 1, 1, 1, 1, NULL, NULL, '2026-04-02 21:07:11', '2026-04-02 21:07:11'),
(2, 'Mpango wa Chakula kwa Jamii', 'mpango-wa-chakula-kwa-jamii', 'Saidia kuandaa milo 3000 na kusaidia familia zenye uhitaji katika jamii.', 'Saidia kuandaa milo 3000 na kusaidia familia zenye uhitaji katika jamii.', '/uploads/frontend/announcements/ann1.jpeg', '2026-04-04 14:52:42', NULL, 1, 1, 1, 2, NULL, NULL, '2026-04-04 14:52:42', '2026-04-04 14:52:42'),
(3, 'Usaili wa Kwaya Umefunguliwa', 'usaili-wa-kwaya-umefunguliwa', 'Jiunge na timu ya sifa na uwe sehemu ya ibada yenye nguvu msimu huu.', 'Jiunge na timu ya sifa na uwe sehemu ya ibada yenye nguvu msimu huu.', '/uploads/frontend/announcements/an2.jpeg', '2026-04-04 14:52:42', NULL, 1, 0, 1, 3, NULL, NULL, '2026-04-04 14:52:42', '2026-04-04 14:52:42'),
(4, 'Retreti ya Wanaume 2025', 'retreti-ya-wanaume-2025', 'Siku tatu za upya wa kiroho, maombi, undugu, na tafakari ya kina ya kiimani.', 'Siku tatu za upya wa kiroho, maombi, undugu, na tafakari ya kina ya kiimani.', '/uploads/frontend/announcements/an3.jpeg', '2026-04-04 14:52:42', NULL, 1, 0, 1, 4, NULL, NULL, '2026-04-04 14:52:42', '2026-04-04 14:52:42'),
(6, 'Usajili wa Kambi ya Vijana', 'usajili-wa-kambi-ya-vijana', 'Wahi kujihakikishia nafasi yako kwa wiki yenye ibada, ukuaji, na mshikamano.', 'Wahi kujihakikishia nafasi yako kwa wiki yenye ibada, ukuaji, na mshikamano.', '/uploads/frontend/announcements/an5.jpeg', '2026-04-04 14:52:42', NULL, 1, 0, 1, 6, NULL, NULL, '2026-04-04 14:52:42', '2026-04-04 14:52:42');
